7	import React from 'react';
8	import { ChakraProvider } from '@salesforce/retail-react-app/app/components/shared/ui';
9	
10	// Removes focus for non-keyboard interactions for the whole application
11	import 'focus-visible/dist/focus-visible';
12	
13	import theme from '../../theme';
14	import { MultiSiteProvider, StoreLocatorProvider } from '@salesforce/retail-react-app/app/contexts';
15	import {
16	  resolveSiteFromUrl,
17	  getParamsFromPath,
18	  getSites,
19	  getLocaleByReference,
20	} from '@salesforce/retail-react-app/app/utils/site-utils';
21	import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
22	import { getEnvBasePath, slasPrivateProxyPath } from '@salesforce/pwa-kit-runtime/utils/ssr-namespace-paths';
23	import { createUrlTemplate } from '@salesforce/retail-react-app/app/utils/url';
24	import createLogger from '@salesforce/pwa-kit-runtime/utils/logger-factory';
25	import { getPasswordlessCallbackUrl } from '@salesforce/retail-react-app/app/utils/auth-utils';
26	
27	import { CommerceApiProvider } from '@salesforce/commerce-sdk-react';
28	import { withReactQuery } from '@salesforce/pwa-kit-react-sdk/ssr/universal/components/with-react-query';
29	import { useCorrelationId } from '@salesforce/pwa-kit-react-sdk/ssr/universal/hooks';
30	import { getAppOrigin } from '@salesforce/pwa-kit-react-sdk/utils/url';
31	import { ReactQueryDevtools } from '@tanstack/react-query-devtools';
32	import { generateSfdcUserAgent } from '@salesforce/retail-react-app/app/utils/sfdc-user-agent-utils';
33	import {
34	  DEFAULT_DNT_STATE,
35	  STORE_LOCATOR_RADIUS,
36	  STORE_LOCATOR_RADIUS_UNIT,
37	  STORE_LOCATOR_DEFAULT_COUNTRY,
38	  STORE_LOCATOR_DEFAULT_COUNTRY_CODE,
39	  STORE_LOCATOR_DEFAULT_POSTAL_CODE,
40	  STORE_LOCATOR_DEFAULT_PAGE_SIZE,
41	  STORE_LOCATOR_SUPPORTED_COUNTRIES,
42	} from '@salesforce/retail-react-app/app/constants';
43	import { ContentfulLivePreviewProvider } from '@contentful/live-preview/react';
44	
45	const sfdcUserAgent = generateSfdcUserAgent();
46	
47	type SiteLocale = {
48	  id: string;
49	  alias?: string;
50	  preferredCurrency: string;
51	};
52	
53	// sfccSiteId overrides the SFCC Commerce API siteId for PWA sites whose ID differs from the
54	// SFCC site ID (e.g. ZimmermannEUfr → SFCC ZimmermannEU).
55	type SiteConfig = {
56	  id: string;
57	  sfccSiteId?: string;
58	  alias?: string;
59	  l10n: {
60	    defaultLocale: string;
61	    supportedLocales: SiteLocale[];
62	  };
63	};
64	
65	type AppLocals = {
66	  appConfig?: {
67	    commerceAPI: {
68	      proxyPath: string;
69	      parameters: {
70	        shortCode: string;
71	        clientId: string;
72	        organizationId: string;
73	        siteId?: string;
74	      };
75	    };
76	    login?: {
77	      passwordless?: {
78	        callbackURI?: string;
79	      };
80	    };
81	    einsteinAPI?: unknown;
82	  };
83	  site?: Pick<SiteConfig, 'id' | 'sfccSiteId' | 'alias'>;
84	  locale?: Pick<SiteLocale, 'id' | 'preferredCurrency'>;
85	  buildUrl?: ReturnType<typeof createUrlTemplate>;
86	  originalUrl?: string;
87	};
88	
89	type AppConfigProps = {
90	  children: React.ReactNode;
91	  locals?: AppLocals;
92	};
93	
94	/**
95	 * Use the AppConfig component to inject extra arguments into the getProps
96	 * methods for all Route Components in the app – typically you'd want to do this
97	 * to inject a connector instance that can be used in all Pages.
98	 *
99	 * You can also use the AppConfig to configure a state-management library such
100	 * as Redux, or Mobx, if you like.
101	 */
102	const AppConfig = ({ children, locals = {} }: AppConfigProps): React.ReactElement => {
103	  const { correlationId } = useCorrelationId();
104	  const headers = {
105	    'correlation-id': correlationId,
106	    sfdc_user_agent: sfdcUserAgent,
107	  };
108	
109	  if (!locals.appConfig) throw new Error('AppConfig: locals.appConfig is required');
110	  const commerceApiConfig = locals.appConfig.commerceAPI;
111	  const locale = locals.locale?.id ?? 'en-US';
112	
113	  const appOrigin = getAppOrigin();
114	  const passwordlessCallbackURI = getPasswordlessCallbackUrl(locals.appConfig?.login?.passwordless?.callbackURI);
115	
116	  const storeLocatorConfig = {
117	    radius: STORE_LOCATOR_RADIUS,
118	    radiusUnit: STORE_LOCATOR_RADIUS_UNIT,
119	    defaultCountry: STORE_LOCATOR_DEFAULT_COUNTRY,
120	    defaultCountryCode: STORE_LOCATOR_DEFAULT_COUNTRY_CODE,
121	    defaultPostalCode: STORE_LOCATOR_DEFAULT_POSTAL_CODE,
122	    defaultPageSize: STORE_LOCATOR_DEFAULT_PAGE_SIZE,
123	    supportedCountries: STORE_LOCATOR_SUPPORTED_COUNTRIES,
124	  };
125	
126	  // Set absolute uris for CommerceApiProvider proxies and callbacks
127	  const redirectURI = `${appOrigin}${getEnvBasePath()}/callback`;
128	  const proxy = `${appOrigin}${getEnvBasePath()}${commerceApiConfig.proxyPath}`;
129	  const slasPrivateClientProxyEndpoint = `${appOrigin}${getEnvBasePath()}${slasPrivateProxyPath}`;
130	
131	  return (
132	    <CommerceApiProvider
133	      shortCode={commerceApiConfig.parameters.shortCode}
134	      clientId={commerceApiConfig.parameters.clientId}
135	      organizationId={commerceApiConfig.parameters.organizationId}
136	      siteId={locals.site?.sfccSiteId ?? locals.site?.id ?? ''}
137	      locale={locale}
138	      currency={locals.locale?.preferredCurrency ?? ''}
139	      redirectURI={redirectURI}
140	      proxy={proxy}
141	      headers={headers}
142	      defaultDnt={DEFAULT_DNT_STATE}
143	      logger={createLogger({ packageName: 'commerce-sdk-react' })}
144	      passwordlessLoginCallbackURI={passwordlessCallbackURI}
145	      // Set 'enablePWAKitPrivateClient' to true to use SLAS private client login flows.
146	      // Make sure to also enable useSLASPrivateClient in ssr.js when enabling this setting.
147	      enablePWAKitPrivateClient={true}
148	      privateClientProxyEndpoint={slasPrivateClientProxyEndpoint}
149	      // Uncomment 'hybridAuthEnabled' if the current site has Hybrid Auth enabled. Do NOT set this flag for hybrid storefronts using Plugin SLAS.
150	      // hybridAuthEnabled={true}
151	    >
152	      <MultiSiteProvider site={locals.site} locale={locals.locale} buildUrl={locals.buildUrl}>
153	        <StoreLocatorProvider config={storeLocatorConfig}>
154	          <ContentfulLivePreviewProvider locale={locale} enableInspectorMode enableLiveUpdates>
155	            <ChakraProvider theme={theme}>{children}</ChakraProvider>
156	          </ContentfulLivePreviewProvider>
157	        </StoreLocatorProvider>
158	      </MultiSiteProvider>
159	      <ReactQueryDevtools />
160	    </CommerceApiProvider>
161	  );
162	};
163	
164	AppConfig.restore = (locals: AppLocals = {}): void => {
165	  const path =
166	    typeof window === 'undefined' ? locals.originalUrl ?? '/' : `${window.location.pathname}${window.location.search}`;
167	
168	  // resolveSiteFromUrl only matches a site alias/ID in the URL. When url.site is 'none' the site
169	  // segment is absent, so it always falls back to the defaultSite. In that case, find the real site
170	  // by matching the locale alias from the URL against each site's supportedLocales.
171	  const defaultResolved = resolveSiteFromUrl(path);
172	  const { localeRef } = getParamsFromPath(path);
173	  type SupportedLocale = { id: string; alias?: string };
174	  // sfccSiteId overrides the SFCC Commerce API siteId for PWA sites that don't share their ID
175	  // with their SFCC counterpart (e.g. ZimmermannEUfr → SFCC ZimmermannEU).
176	  type Site = {
177	    id: string;
178	    sfccSiteId?: string;
179	    alias?: string;
180	    l10n: { defaultLocale: string; supportedLocales: SupportedLocale[] };
181	  };
182	  const site: Site = localeRef
183	    ? (getSites() as Site[]).find((s) =>
184	        s.l10n.supportedLocales.some((l) => l.alias === localeRef || l.id === localeRef),
185	      ) ?? defaultResolved
186	    : defaultResolved;
187	
188	  // resolveLocaleFromUrl also calls resolveSiteFromUrl internally, so it would return the wrong
189	  // site too. Resolve the locale directly from the site we already found above.
190	  const locale = (getLocaleByReference(site, localeRef ?? site.l10n.defaultLocale) ??
191	    getLocaleByReference(site, site.l10n.defaultLocale)) as SiteLocale;
192	
193	  const { app: appConfig } = getConfig() as { app: NonNullable<AppLocals['appConfig']> };
194	  const apiConfig = {
195	    ...appConfig.commerceAPI,
196	    einsteinConfig: appConfig.einsteinAPI,
197	  };
198	
199	  apiConfig.parameters.siteId = site.sfccSiteId ?? site.id;
200	
201	  locals.buildUrl = createUrlTemplate(appConfig, site.alias || site.id, locale.alias || locale.id);
202	  locals.site = site;
203	  locals.locale = locale;
204	  locals.appConfig = appConfig;
205	};
206	
207	AppConfig.freeze = (): undefined => undefined;
208	
209	AppConfig.extraGetPropsArgs = (locals: AppLocals = {}): Record<string, unknown> => {
210	  return {
211	    buildUrl: locals.buildUrl,
212	    site: locals.site,
213	    locale: locals.locale,
214	  };
215	};
216	
217	const isServerSide = typeof window === 'undefined';
218	
219	// Recommended settings for PWA-Kit usages.
220	// NOTE: they will be applied on both server and client side.
221	// retry is always disabled on server side regardless of the value from the options
222	const options = {
223	  queryClientConfig: {
224	    defaultOptions: {
225	      queries: {
226	        retry: false,
227	        refetchOnWindowFocus: false,
228	        staleTime: 10 * 1000,
229	        ...(isServerSide ? { retryOnMount: false } : {}),
230	      },
231	      mutations: {
232	        retry: false,
233	      },
234	    },
235	  },
236	};
237	
238	export default withReactQuery(AppConfig, options);
239
